const v3=(x,y,z)=>new T.Vector3(x,y,z);
function merged(parts){const pos=[],norm=[],uv=[];for(let geometry of parts){const g=geometry.index?geometry.toNonIndexed():geometry;pos.push(...g.attributes.position.array);norm.push(...g.attributes.normal.array);if(g.attributes.uv)uv.push(...g.attributes.uv.array);else uv.push(...new Array(g.attributes.position.count*2).fill(0));if(g!==geometry)g.dispose();geometry.dispose();}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setAttribute('normal',new T.Float32BufferAttribute(norm,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));return g;}
function canvasTexture(size,draw){if(typeof document==='undefined')return null;const c=document.createElement('canvas');c.width=c.height=size;const cx=c.getContext('2d');draw(cx,size);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
function snowTexture(){const t=canvasTexture(256,(c,n)=>{const rand=rng(961),im=c.createImageData(n,n);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=(y*n+x)*4;const n1=rand()*12+Math.sin(x*.20+y*.024)*2;im.data[i]=235+n1;im.data[i+1]=240+n1;im.data[i+2]=244+n1;im.data[i+3]=255;}c.putImageData(im,0,0);for(let i=0;i<900;i++){c.fillStyle=i%3?'#ffffff55':'#9daebb33';c.fillRect(rand()*n,rand()*n,.5+rand()*1.2,.5+rand()*1.2);}});if(t){t.wrapS=t.wrapT=T.RepeatWrapping;t.repeat.set(65,320);t.anisotropy=4;}return t;}
function pineGeometry(){const green=[],snow=[];const rand=rng(167);for(let tier=0;tier<6;tier++){const y=1.1+tier*.76,width=1.55*(1-tier/7);let core=new T.ConeGeometry(width*.52,1.8,9,1);core.translate(0,y+.65,0);green.push(core);for(let i=0;i<7;i++){const a=i*Math.PI*2/7+tier*.43,len=width*(.8+rand()*.3);const root=v3(0,y,0),tip=v3(Math.sin(a)*len,y-.20,Math.cos(a)*len);const d=tip.clone().sub(root),q=new T.Quaternion().setFromUnitVectors(v3(0,1,0),d.clone().normalize());let g=new T.ConeGeometry(width*.22,d.length(),5,1);g.applyQuaternion(q);g.translate(...root.clone().add(tip).multiplyScalar(.5).toArray());green.push(g);let cap=new T.ConeGeometry(width*.175,d.length()*.96,5,1);cap.applyQuaternion(q);cap.scale(1,.4,1);cap.translate(Math.sin(a)*len*.5,y+.12,Math.cos(a)*len*.5);snow.push(cap);}}const tip=new T.ConeGeometry(.24,1.1,7);tip.translate(0,5.85,0);snow.push(tip);return {green:merged(green),snow:merged(snow),trunk:new T.CylinderGeometry(.12,.24,5.4,7).translate(0,2.7,0)};}
function rockGeometry(){const g=new T.IcosahedronGeometry(1,2),p=g.attributes.position,colors=[],rand=rng(849);for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);const noise=1+.09*Math.sin(x*17+z*9)+.08*Math.cos(y*19+x*8);p.setXYZ(i,x*noise,y*.80*noise,z*noise);const cap=y>.2+Math.sin(x*10+z*13)*.1;const c=new T.Color(cap?0xf0f5f6:0x737f8a);c.multiplyScalar(.9+rand()*.15);colors.push(c.r,c.g,c.b);}g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.computeVertexNormals();return g;}
function instances(root,geo,mat,list,shadow=true,split=true){if(split&&list.length>120){const chunks=new Map(),group=new T.Group();root.add(group);for(const item of list){const key=Math.floor(-item.z/150);if(!chunks.has(key))chunks.set(key,[]);chunks.get(key).push(item);}for(const chunk of chunks.values())instances(group,geo,mat,chunk,shadow,false);return group;}const mesh=new T.InstancedMesh(geo,mat,Math.max(1,list.length));mesh.count=list.length;const temp=new T.Object3D();for(let i=0;i<list.length;i++){const o=list[i];temp.position.set(o.x,o.y,o.z);temp.rotation.set(o.rx||0,o.ry||0,o.rz||0);temp.scale.set(o.sx??o.s??1,o.sy??o.s??1,o.sz??o.s??1);temp.updateMatrix();mesh.setMatrixAt(i,temp.matrix);}mesh.instanceMatrix.needsUpdate=true;mesh.castShadow=shadow;mesh.receiveShadow=true;mesh.computeBoundingSphere();root.add(mesh);return mesh;}
