function segment(root,a,b,radius,material){const d=b.clone().sub(a),o=mesh(root,new T.CapsuleGeometry(radius,Math.max(.01,d.length()-2*radius),4,8),material);o.position.copy(a.clone().add(b).multiplyScalar(.5));o.quaternion.setFromUnitVectors(v3(0,1,0),d.normalize());return o;}
