 const pack=mesh(body,new T.SphereGeometry(1,14,10),mat(index===1?0xc5ad7c:0x35454d),0,1.01,.48);pack.scale.set(.19,.25,.1);for(const side of [-1,1])segment(body,v3(side*.17,1.17,.07),v3(side*.18,.85,.07),.017,strap);
