 const sling=new T.Group();sling.name='start-slingshot';env.add(sling);const slingWood=new T.MeshStandardMaterial({color:0x74513a,roughness:.65}),slingMetal=new T.MeshStandardMaterial({color:0xc4b274,roughness:.28,metalness:.72}),slingRubber=new T.MeshStandardMaterial({color:0xeeb25c,roughness:.48});const bands=[];
