 for(let d=40;d<level.length-30;d+=13){const sec=sectionAt(level,d);if(sec.type==='forest')for(const side of [-1,1]){const x=side*(11+random()*6);trees.push({x,y:terrainHeight(x,d,level),z:-d,s:1.15+random()*.6,ry:random()*6.28});}if(sec.type==='canyon')for(const side of [-1,1]){const x=side*(12+random()*2);banks.push({x,y:terrainHeight(x,d,level)+1.3,z:-d,sx:2.4,sy:4.0+random()*3,sz:5.3,ry:random()});}}
